OK, it looks like in python 3.14.2, iterables unpacked with `[*myiterable]` do not mask the errors, they correctly show the underlying error that happened when the `__next__()` and `__iter__()` methods are invoked:

```python
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(slots=True)
class Outcome:
    case_id: str
    iterator: object
    error_str: str


class HasIter:
    def __init__(
        self,
        *,
        raises_on_iter: type[Exception] | None = None,
        raises_on_next: type[Exception] | None = None,
    ):
        self.raises_on_iter = raises_on_iter
        self.raises_on_next = raises_on_next

    def __iter__(self):
        if self.raises_on_iter:
            raise self.raises_on_iter(f"error in {type(self).__name__}.__iter__")
        return HasNext(raises_on_next=self.raises_on_next)

    def __getitem__(self, index: int) -> int:
        print("THIS SHOULD NOT BE CALLED SINCE __iter__ IS PRESENT")
        raise AssertionError(
            "__getitem__ should not be called when __iter__ is present"
        )


class HasNext:
    def __init__(self, *, raises_on_next: type[Exception] | None = None):
        self.i = 0
        self.raises_on_next = raises_on_next

    def __next__(self) -> int:
        if self.raises_on_next:
            raise self.raises_on_next(f"error in {type(self).__name__}.__next__")
        if self.i < 3:
            value = self.i
            self.i += 1
            return value
        raise StopIteration


class OnlyHasGetitem:
    def __init__(self, raises_on_getitem: type[Exception] | None = None):
        self.raises_on_getitem = raises_on_getitem

    def __getitem__(self, index: int) -> int:
        if self.raises_on_getitem:
            raise self.raises_on_getitem(f"error in {type(self).__name__}.__getitem__")
        if index < 3:
            return index + 1
        raise IndexError


class HasNothing:
    pass


def run_case(*, id: str, obj: Any) -> Outcome:
    try:
        _result = [*obj]
        error_str = ""
    except Exception as exc:
        error_str = f"{type(exc).__name__}: {exc}"
    return Outcome(case_id=id, iterator=obj, error_str=error_str)


def emit_markdown_table(outcomes: list[Outcome]) -> None:
    case_header = "case"
    error_header = "error"
    case_width = max(len(case_header), *(len(row.case_id) for row in outcomes))
    error_width = max(len(error_header), *(len(row.error_str) for row in outcomes))

    print(f"| {case_header.ljust(case_width)} | {error_header.ljust(error_width)} |")
    print(f"| {'-' * case_width} | {'-' * error_width} |")
    for row in outcomes:
        print(
            f"| {row.case_id.ljust(case_width)} | {row.error_str.ljust(error_width)} |"
        )


def main() -> None:
    error_options: list[type[Exception] | None] = [
        None,
        ValueError,
        AttributeError,
    ]

    def error_name(exc: type[Exception] | None) -> str:
        return exc.__name__ if exc else "None"

    outcomes: list[Outcome] = []

    for raises_on_iter in error_options:
        for raises_on_next in error_options:
            probe = HasIter(
                raises_on_iter=raises_on_iter,
                raises_on_next=raises_on_next,
            )
            outcomes.append(
                run_case(
                    id=f"HasIter(raises_on_iter={error_name(raises_on_iter)}, raises_on_next={error_name(raises_on_next)})",
                    obj=probe,
                )
            )

    for raises_on_getitem in error_options:
        probe = OnlyHasGetitem(raises_on_getitem=raises_on_getitem)
        outcomes.append(
            run_case(
                id=f"OnlyHasGetitem(raises_on_getitem={error_name(raises_on_getitem)})",
                obj=probe,
            )
        )

    outcomes.append(run_case(id="HasNothing", obj=HasNothing()))

    emit_markdown_table(outcomes)


if __name__ == "__main__":
    main()
