+        // e.g. if PYTHON_THREAD_INHERIT_CONTEXT=1 is set.
+        // In that case, we need to make a copy of context otherwise we
+        // would be sharing the same context as the parent thread.
+        // This is needed as decimal module mutates the context directly
+        // rather than setting a new context via PyContextVar_Set.
+        PyThreadState *tstate = _PyThreadState_GET();
+        if (_PyDecContextObject_CAST(tl_context)->tstate == tstate) {
+            return tl_context;
