+        Py_INCREF(copy);
+        // Set the copy as the current context for this thread,
+        // so that subsequent calls get the correct context.
+        PyObject *tok = PyContextVar_Set(state->current_context_var, copy);
+        Py_DECREF(tok);
+        Py_DECREF(tl_context);
+        return copy;
     }

     return init_current_context(state);

